		fmt.Fprintf(w, "%s hooks are not installed.\n", ag.Type())
		return nil
	}

	if err := hookAgent.UninstallHooks(ctx); err != nil {
		return fmt.Errorf("failed to remove %s hooks: %w", ag.Type(), err)
	}
